import unittest
from candidate import rolling_max

class TestRollingMax(unittest.TestCase):
    def test_rolling_max_example(self):
        self.assertEqual(rolling_max([1, 2, 3, 2, 3, 4, 2]), [1, 2, 3, 3, 3, 4, 4])

    def test_rolling_max_single_element(self):
        self.assertEqual(rolling_max([5]), [5])

    def test_rolling_max_empty_list(self):
        self.assertEqual(rolling_max([]), [])

    def test_rolling_max_negative_numbers(self):
        self.assertEqual(rolling_max([-5, -2, -3, -2, -3, -4, -2]), [-5, -2, -2, -2, -2, -2, -2])

    def test_rolling_max_mixed_numbers(self):
        self.assertEqual(rolling_max([-5, 2, 3, -2, 3, 4, -2]), [-5, 2, 3, 3, 3, 4, 4])

    def test_rolling_max_non_integer_input(self):
        with self.assertRaises(TypeError):
            rolling_max(['a', 'b', 'c'])

    def test_rolling_max_none_input(self):
        with self.assertRaises(TypeError):
            rolling_max(None)

if __name__ == '__main__':
    unittest.main()
